# Build mapping from parsed names to a phone contact email (exact first_name match)
parsed = [{'name': 'Glen', 'direction': 'owe_me', 'amount': 285.0}, {'name': 'Norman', 'direction': 'owe_me', 'amount': 115.0}, {'name': 'Cory', 'direction': 'owes_me', 'amount': 212.0}, {'name': 'Edwin', 'direction': 'owes_me', 'amount': 70.0}, {'name': 'Katherine', 'direction': 'owe_me', 'amount': 171.0}, {'name': 'Jeremy', 'direction': 'owes_me', 'amount': 149.0}]

name_to_email_candidates = {}
for nm in [r['name'] for r in parsed]:
    cs = friend_contacts[nm]
    # candidates where first_name exactly matches
    exact = [c for c in cs if c['first_name'].lower()==nm.lower()]
    name_to_email_candidates[nm] = exact
    print(nm, 'exact candidates', len(exact))
    for c in exact:
        print('  email', c.get('email'), 'phone', c.get('phone_number'), 'contact_id', c['contact_id'], 'name', c['first_name'], c['last_name'])

# Choose email: if exactly one candidate, use it; otherwise choose first by list order
name_to_email = {}
for nm, cand in name_to_email_candidates.items():
    if len(cand)==0:
        raise Exception('No contact candidates for '+nm)
    if len(cand)>1:
        print('WARNING multiple candidates for', nm, 'choosing first')
    name_to_email[nm] = cand[0]['email']

print('name_to_email chosen:', name_to_email)

# Now search venmo users by email for each person

def search_venmo_users(query, page_limit=20):
    allu=[]
    page_index=0
    while True:
        res = apis.venmo.search_users(access_token=venmo_access_token, query=query, page_index=page_index, page_limit=page_limit)
        print('venmo search_users query', query, 'page', page_index, 'count', len(res))
        allu.extend(res)
        if len(res) < page_limit:
            break
        page_index += 1
    return allu

venmo_email_to_user = {}
for nm, email in name_to_email.items():
    users = search_venmo_users(query=email)
    # exact email match
    exact = [u for u in users if u['email'].lower()==email.lower()]
    print('Venmo users for', nm, 'email', email, 'exact matches', len(exact))
    for u in users:
        print('  user', u['first_name'], u['last_name'], 'email', u['email'])
    if len(exact)==0:
        # fallback: use first
        venmo_email_to_user[nm] = users[0]
        print('  using first user due to no exact match')
    else:
        venmo_email_to_user[nm] = exact[0]

print('venmo_email_to_user:', {nm:venmo_email_to_user[nm]['email'] for nm in venmo_email_to_user})

